<section class="admin-page-head"><div><p class="admin-kicker">INVENTARIO M05</p><h1>Existencias por sucursal</h1><p>El saldo disponible se deriva de existencia física menos cantidad apartada.</p></div><div class="admin-head-actions"><a class="admin-secondary-button" href="/admin/inventory/movements">Movimientos</a><?php if(($capabilities['inventory.adjust']??false)||($capabilities['inventory.initial']??false)):?><a class="admin-primary-button" href="/admin/inventory/adjustments">+ Registrar</a><?php endif?></div></section>
<form class="admin-panel admin-filter-bar admin-inventory-filter" method="get"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Producto, variante o SKU"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><option value="low" <?= $status==='low'?'selected':'' ?>>En mínimo</option><option value="out" <?= $status==='out'?'selected':'' ?>>Agotados</option><option value="uninitialized" <?= $status==='uninitialized'?'selected':'' ?>>Sin inicializar</option></select></label><button class="admin-secondary-button">Aplicar</button></form>
<section class="admin-panel admin-table-panel"><?php if($page->items===[]):?><div class="admin-empty"><strong>Sin existencias registradas</strong><span>No se crean saldos ficticios. Registra una existencia inicial cuando el conteo real esté confirmado.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Variante</th><th>Sucursal</th><th>Física</th><th>Apartada</th><th>Disponible</th><th>Mínimo</th><th></th></tr></thead><tbody><?php foreach($page->items as$row):?><tr><td><strong><?= e($row['product_name']) ?></strong><small><?= e($row['sku'].' · '.$row['variant_name']) ?></small></td><td><?= e($row['branch_name']) ?></td><td><?= e($row['physical_quantity'].' '.$row['symbol']) ?></td><td><?= e($row['reserved_quantity'].' '.$row['symbol']) ?></td><td><strong><?= e($row['available_quantity'].' '.$row['symbol']) ?></strong><?php if((int)$row['is_low']===1):?><small class="admin-stock-warning">Requiere revisión</small><?php endif?></td><td><?= $row['minimum_quantity']===null?'Sin configurar':e($row['minimum_quantity'].' '.$row['symbol']) ?></td><td class="admin-actions"><a class="admin-secondary-button" href="/admin/inventory/movements?branch_id=<?= e($row['branch_id']) ?>&variant_id=<?= e($row['variant_id']) ?>">Historial</a><?php if($capabilities['inventory.thresholds']??false):?><form method="post" action="/admin/inventory/thresholds"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="branch_id" value="<?= e($row['branch_id']) ?>"><input type="hidden" name="variant_id" value="<?= e($row['variant_id']) ?>"><label class="admin-visually-labeled"><span class="sr-only">Mínimo</span><input name="minimum_quantity" inputmode="decimal" required value="<?= e($row['minimum_quantity']??'0') ?>"></label><button class="admin-quiet-button">Guardar mínimo</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
